package kr.memorynotes;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.Bitmap;import org.json.*;import java.time.LocalDate;import java.util.*;import java.io.*;
public class LibraryUiRunner extends Instrumentation {
 boolean darkOnly;int assertions;MainActivity a;NoteDb db;JSONObject snapshot;String draft;boolean dark;int headerY;
 void check(boolean value,String message){assertions++;if(!value)throw new AssertionError(message);}
 void ui(Runnable task){final Throwable[] failure=new Throwable[1];runOnMainSync(()->{try{task.run();}catch(Throwable t){failure[0]=t;}});waitForIdleSync();if(failure[0]!=null)throw new RuntimeException(failure[0]);}
 void capture(String name)throws Exception{android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();if(window!=null){for(android.view.accessibility.AccessibilityNodeInfo node:window.findAccessibilityNodeInfosByText("Wait"))node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);}SystemClock.sleep(1200);Bitmap b=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 public void onCreate(Bundle args){super.onCreate(args);darkOnly=args!=null&&"true".equals(args.getString("darkOnly"));start();}
 public void onStart(){if(darkOnly){darkProbe();return;}Bundle result=new Bundle();int code=Activity.RESULT_OK;try{
  a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));db=a.db;snapshot=db.snapshot();draft=a.getPreferences(0).getString("draft","");dark=a.getPreferences(0).getBoolean("dark",false);
  db.getWritableDatabase().delete("notes",null,null);db.getWritableDatabase().delete("history",null,null);
  String other=db.addGroup("subjects","추가 과목",null);String chapter=db.groups("chapters","hvac").keySet().iterator().next();String chapterName=db.groups("chapters","hvac").get(chapter);String otherChapter=db.addGroup("chapters","기초",other);
  for(int i=0;i<7;i++){Note n=new Note();n.subject=i<4?"hvac":other;n.chapter=i==6?"":i<4?chapter:otherChapter;n.title="목록 검증 "+i;n.body="스크롤 확인용 내용\n공조냉동 노트";n.due=i<5?"":LocalDate.now().plusDays(1).toString();n.type=i%2==0?"일반 노트":"문답 카드";n.question="문제 "+i;n.answer="답 "+i;db.save(n);}
  ui(()->{a.getPreferences(0).edit().remove("draft").putBoolean("dark",false).commit();a.show("홈");});ui(()->{});
  ui(()->{TextView summary=a.root.findViewWithTag("home.summary");check(summary.getText().toString().contains("전체 노트 7개 · 오늘 복습 5개"),"total and due counts distinct");LinearLayout cards=a.root.findViewWithTag("note.results");check(cards.getChildCount()==7,"home contains every note");ScrollView scroll=a.root.findViewWithTag("note.list");check(scroll.getHeight()>100,"note viewport usable");check(scroll.canScrollVertically(1),"home list scrolls");int[] xy=new int[2];a.root.findViewWithTag("home.header").getLocationOnScreen(xy);headerY=xy[1];scroll.setSmoothScrollingEnabled(false);scroll.fullScroll(View.FOCUS_DOWN);});ui(()->{});
  ui(()->{ScrollView scroll=a.root.findViewWithTag("note.list");check(scroll.getScrollY()>0,"home reaches last notes");int[] xy=new int[2];a.root.findViewWithTag("home.header").getLocationOnScreen(xy);check(xy[1]==headerY,"header remains fixed");});capture("home-light.png");
  ui(()->a.show("검색"));ui(()->{});
  ui(()->{Spinner ch=a.root.findViewWithTag("filter.chapter");check(ch.getCount()>2,"all subjects expose chapters");check(((LinearLayout)a.root.findViewWithTag("note.results")).getChildCount()==7,"search contains seven");int choice=-1;for(int i=0;i<ch.getCount();i++)if(ch.getItemAtPosition(i).toString().equals("공조냉동 · "+chapterName))choice=i;check(choice>=0,"qualified chapter available");ch.setSelection(choice);});ui(()->{});
  ui(()->check(((LinearLayout)a.root.findViewWithTag("note.results")).getChildCount()==4,"chapter selection limits search"));
  ui(()->{Spinner subjects=a.root.findViewWithTag("filter.subject");subjects.setSelection(subjects.getCount()-1);});ui(()->{});
  ui(()->{Spinner ch=a.root.findViewWithTag("filter.chapter");check(ch.getCount()==3,"changing subject rebuilds chapter list");check(((LinearLayout)a.root.findViewWithTag("note.results")).getChildCount()==3,"subject change clears old chapter");});capture("search-light.png");
  final ReviewPicker[] picker=new ReviewPicker[1];ui(()->picker[0]=new ReviewPicker(a,false,""));ui(()->{});
  ui(()->{ReviewPicker p=picker[0];check(p.selected().size()==7,"whole review includes all seven");p.range.setSelection(1);});ui(()->{});ui(()->{check(picker[0].selected().size()==5,"today review includes five");picker[0].range.setSelection(0);picker[0].filters.subjects.setSelection(picker[0].filters.subjectIds.indexOf("hvac"));});ui(()->{});
  ui(()->{check(picker[0].selected().size()==4,"review subject scope");picker[0].filters.type.setSelection(2);});ui(()->{});
  ui(()->{check(picker[0].selected().size()==2,"review intersects subject and type");picker[0].dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});
  ui(()->check(a.review!=null&&a.review.notes.size()==2,"review starts selected notes only"));
  ui(()->{a.getPreferences(0).edit().putBoolean("dark",true).commit();a.show("홈");});ui(()->{});capture("home-dark.png");ui(()->{picker[0]=new ReviewPicker(a,false,"");});ui(()->{android.graphics.drawable.Drawable background=picker[0].dialog.getWindow().getDecorView().getBackground();while(background instanceof android.graphics.drawable.InsetDrawable)background=((android.graphics.drawable.InsetDrawable)background).getDrawable();check(background instanceof android.graphics.drawable.GradientDrawable&&((android.graphics.drawable.GradientDrawable)background).getColor().getDefaultColor()==a.u.surface,"dark review dialog uses matching surface");});capture("review-dark.png");ui(()->picker[0].dialog.dismiss());
  result.putString("stream","PASS "+assertions+" home, chapter search and review Android assertions\n");
 }catch(Throwable t){code=Activity.RESULT_CANCELED;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(t));}finally{if(db!=null&&snapshot!=null)try{db.restore(snapshot);String saved=draft;boolean savedDark=dark;ui(()->{a.getPreferences(0).edit().putString("draft",saved==null?"":saved).putBoolean("dark",savedDark).commit();a.finish();});}catch(Exception ignored){}}finish(code,result);}
 void darkProbe(){Bundle result=new Bundle();int code=Activity.RESULT_OK;final ReviewPicker[] dialog=new ReviewPicker[1];try{
  a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));dark=a.getPreferences(0).getBoolean("dark",false);
  ui(()->{a.getPreferences(0).edit().putBoolean("dark",true).commit();a.show("홈");});ui(()->dialog[0]=new ReviewPicker(a,false,""));
  ui(()->{android.graphics.drawable.Drawable background=dialog[0].dialog.getWindow().getDecorView().getBackground();while(background instanceof android.graphics.drawable.InsetDrawable)background=((android.graphics.drawable.InsetDrawable)background).getDrawable();check(background instanceof android.graphics.drawable.GradientDrawable&&((android.graphics.drawable.GradientDrawable)background).getColor().getDefaultColor()==a.u.surface,"dark dialog surface after onShow");check(a.u.ink==android.graphics.Color.parseColor("#EEF6F1"),"dark dialog foreground");});capture("review-dark.png");result.putString("stream","PASS 2 dark dialog Android assertions\n");
 }catch(Throwable t){code=Activity.RESULT_CANCELED;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(t));}finally{if(a!=null)ui(()->{if(dialog[0]!=null)dialog[0].dialog.dismiss();a.getPreferences(0).edit().putBoolean("dark",dark).commit();a.finish();});}finish(code,result);}

}
